WITH sales_agg AS ( SELECT ca.ca_state AS state, SUM(ss.ss_net_profit) AS total_sales_profit, SUM(ss.ss_ext_sales_price) AS total_sales_amount, COUNT(*) AS sales_transactions FROM store_sales ss JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk JOIN customer_address ca ON ss.ss_addr_sk = ca.ca_address_sk WHERE ss.ss_sold_date_sk BETWEEN 2451000 AND 2452000 GROUP BY ca.ca_state ), store_returns_agg AS ( SELECT ca.ca_state AS state, SUM(sr.sr_net_loss) AS total_store_return_loss FROM store_returns sr JOIN customer c ON sr.sr_customer_sk = c.c_customer_sk JOIN customer_address ca ON sr.sr_addr_sk = ca.ca_address_sk WHERE sr.sr_returned_date_sk BETWEEN 2451000 AND 2452000 GROUP BY ca.ca_state ), catalog_returns_agg AS ( SELECT ca.ca_state AS state, sm.sm_type AS ship_mode_type, SUM(cr.cr_net_loss) AS total_catalog_return_loss FROM catalog_returns cr JOIN customer c ON cr.cr_returning_customer_sk = c.c_customer_sk JOIN customer_address ca ON cr.cr_returning_addr_sk = ca.ca_address_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk WHERE cr.cr_returned_date_sk BETWEEN 2451000 AND 2452000 AND cr.cr_ship_mode_sk IN (7, 12) GROUP BY ca.ca_state, sm.sm_type ) SELECT s.state, s.total_sales_profit, s.total_sales_amount, s.sales_transactions, COALESCE(r.total_store_return_loss, 0) AS total_store_return_loss, COALESCE(ca.total_catalog_return_loss, 0) AS total_catalog_return_loss, s.total_sales_profit - COALESCE(r.total_store_return_loss, 0) - COALESCE(ca.total_catalog_return_loss, 0) AS net_profit_after_returns, (COALESCE(r.total_store_return_loss, 0) + COALESCE(ca.total_catalog_return_loss, 0)) / NULLIF(s.total_sales_amount, 0) AS return_loss_rate, s.total_sales_profit / NULLIF(s.sales_transactions, 0) AS avg_profit_per_transaction, RANK() OVER (ORDER BY s.total_sales_profit - COALESCE(r.total_store_return_loss, 0) - COALESCE(ca.total_catalog_return_loss, 0) DESC) AS profit_rank, ca.ship_mode_type FROM sales_agg s LEFT JOIN store_returns_agg r ON s.state = r.state LEFT JOIN catalog_returns_agg ca ON s.state = ca.state ORDER BY net_profit_after_returns DESC LIMIT 10
